// PII-Schutz: Briefing-Inhalte (Ziel-Titel) duerfen NIE an ein Cloud-Modell.
// Case-insensitiv auf den ganzen 'cloud'-Marker (faengt ':cloud' UND '-cloud',
// z.B. gpt-oss:120b-cloud).
const body = $input.first().json.body || {};
const model = String(body.model || '');
if (!model) {
  throw new Error('Kein Modell angegeben.');
}
if (model.toLowerCase().includes('cloud')) {
  throw new Error('PII-Schutz: Cloud-Modell "' + model + '" ist fuer Briefing-Inhalte verboten.');
}
if (!body.prompt) {
  throw new Error('Unvollstaendige Nutzlast (prompt fehlt).');
}
return $input.all();

// Ollama /api/generate liefert { response: "<freier Text>", ... }.
// Als { text } zurueckgeben - responseMode:lastNode macht das zur HTTP-Antwort.
const roh = $input.first().json.response;
return [{ json: { text: String(roh == null ? '' : roh).trim() } }];
